(function(){'use strict';const G=DecideCatalogEquipment,section=document.createElement('details');section.id='equipmentWindow';section.className='equipment-window';const summary=document.createElement('summary');summary.textContent='อุปกรณ์สวมใส่';const body=document.createElement('div');section.append(summary,body);$('characterPanel').before(section);let selected='rightHand',message='';
const add=(tag,text,parent)=>{const el=document.createElement(tag);if(text)el.textContent=text;parent.append(el);return el;};
function icon(r){if(!r)return 'assets/items/unknown.svg';return r.icon||'assets/items/'+(r.training?'training-'+r.id:r.kind+'-'+r.id)+'.svg';}
function image(r,parent){const img=document.createElement('img');img.src=icon(r);img.alt='';img.onerror=()=>{img.onerror=null;img.src='assets/items/unknown.svg';};parent.append(img);return img;}
function run(fn){try{s=fn();save();render();message='บันทึกอุปกรณ์แล้ว';}catch(e){message=e.message;}draw();}
function describe(r){const a=[];if(r.damageDice)a.push('ดาเมจ '+r.damageDice);if(r.element)a.push('ธาตุ '+r.element+(r.elementDamage?' +'+r.elementDamage:''));if(r.attackBonus)a.push('Attack +'+r.attackBonus);if(r.defense)a.push('DEF +'+r.defense);if(r.handedness)a.push(r.handedness);if(r.ability)a.push(r.ability);if(r.power!==undefined)a.push('พลัง '+r.power);return a.join(' · ');}
function draw(){if(!section.open)return;body.replaceChildren();if(!s.character)return;const rows=R.records(DB),eq=G.read(s),stats=G.stats(s,rows),locked=!!s.expedition||s.dead||!!s.event;const heading=add('div','',body);heading.className='equipment-heading';add('h2','เครื่องแต่งกายและอาวุธ',heading);const status=add('p',message,heading);status.id='equipmentStatus';status.setAttribute('role','status');const layout=add('div','',body);layout.className='equipment-layout';const paper=add('div','',layout);paper.className='equipment-paper';const center=add('div','',paper);center.className='equipment-character';if(s.character.images?.icon){const img=add('img','',center);img.src=s.character.images.icon;img.alt=s.character.name;}else{const silhouette=add('img','',center);silhouette.src='assets/items/player-placeholder.svg';silhouette.alt='ยังไม่ได้ใส่ไอคอนผู้เล่น';}add('strong',s.character.name,center);add('small','Lv. '+s.character.level,center);add('small','HP สูงสุด '+DecideCreation.maxHp(s.character)+' · MP '+s.maxMp,center);
const left=['helmet','armor','cloak','boots','accessory1'],right=['rightHand','leftHand','accessory2','accessory3','accessory4'];for(const [side,keys]of [[1,left],[3,right]])for(const [i,key]of keys.entries()){const ref=eq.slots[key],r=G.row(ref,rows),reserved=key==='leftHand'&&eq.slots.rightHand?.twoHanded,b=add('button','',paper);b.type='button';b.className='equipment-slot'+(selected===key?' selected':'')+(reserved?' reserved':'');b.dataset.slot=key;b.style.gridColumn=side;b.style.gridRow=i+1;b.setAttribute('aria-pressed',String(selected===key));image(r||reserved&&G.row(eq.slots.rightHand,rows),b);const label=add('span','',b);add('small',G.slots[key],label);add('strong',reserved?'ใช้ร่วมกับอาวุธสองมือ':r?.displayName||ref?.name||'ว่าง',label);b.onclick=()=>{selected=key;message='';draw();};}
const bag=add('div','',layout);bag.className='equipment-bag';add('h3',G.slots[selected]+' — เลือกของจากคลัง',bag);const current=eq.slots[selected],currentRow=G.row(current,rows);if(current){add('p',currentRow?.displayName||current.name,bag);add('small',currentRow?describe(currentRow):'รายการต้นทางไม่พร้อมใช้งาน',bag);const takeOff=add('button','ถอดเข้าคลัง',bag);takeOff.id='equipmentUnequip';takeOff.disabled=locked;takeOff.onclick=()=>run(()=>G.unequip(s,rows,selected));}
const inv=DecideCatalogEconomy.validate(s.catalogInventory),counts=new Map();for(const ref of inv.gearStash){const key=ref.refType+'::'+ref.name;counts.set(key,(counts.get(key)||0)+1);}const candidates=[];for(const [key,count]of counts){const [kind,name]=key.split('::'),r=rows.find(x=>x.kind===kind&&x.name===name&&x.enabled!==false);if(r)candidates.push({r,count,kind,id:r.id});}for(const id of [...new Set(s.character.inventory?.weapons||[])]){const r=G.row({kind:'training',id},rows);if(r)candidates.push({r,count:s.character.inventory.weapons.filter(x=>x===id).length,kind:'training',id});}
let shown=0;for(const entry of candidates){const {r,count,kind,id}=entry,expected=selected.startsWith('accessory')?'accessory':['rightHand','leftHand'].includes(selected)?'hand':selected,type=r.kind==='armor'?(r.equipSlot||'armor'):r.kind;if(expected==='hand'?!['weapon','leftHand'].includes(type):type!==expected)continue;shown++;const card=add('div','',bag);card.className='equipment-item';card.dataset.equipItem=id;image(r,card);const info=add('div','',card);add('strong',(r.displayName||r.name)+' ×'+count,info);add('small',describe(r),info);if(r.passive||r.passiveEffects)add('small',r.passive||r.passiveEffects,info);if(r.specialEffectsText)add('small','เอฟเฟกต์บรรยายพิเศษยังไม่รองรับครบในสนาม',info);const reason=G.compatible(s,selected,r);if(reason)add('small',reason,info);const b=add('button','ใส่',card);b.disabled=!!reason||locked;b.onclick=()=>run(()=>G.equip(s,R.records(DB),selected,kind,id));}
if(!shown)add('p','ยังไม่มีของที่ตรงกับช่องนี้ในคลัง',bag);const bonus=add('p','โบนัสรวม: '+Object.entries(stats.bonuses).filter(([,v])=>v).map(([k,v])=>k.toUpperCase()+' '+(v>0?'+':'')+v).join(' · '),body);bonus.className='equipment-bonuses';add('p','ซื้ออุปกรณ์พื้นฐานได้ที่ร้านค้า → ช่างอุปกรณ์ • เปลี่ยนรูปของแต่ละชิ้นได้ที่ฐานข้อมูล → ไอคอนของชิ้นนี้',body).className='equipment-note';if(locked)add('p','จบการต่อสู้หรือเหตุการณ์ก่อนเปลี่ยนอุปกรณ์',body);}
section.addEventListener('toggle',draw);window.DecideEquipmentUI={draw,icon};
})();
